```javascript
// app/javascript/controllers/location_controller.js (lines 786-812)
waitForOption(selectElement, value, timeout = 5000) {
  return new Promise((resolve, reject) => {
    const existingOption = selectElement.querySelector(`option[value="${value}"]`);
    if (existingOption) {
      resolve(existingOption);
      return;
    }

    const observer = new MutationObserver(() => {
      const option = selectElement.querySelector(`option[value="${value}"]`);
      if (option) {
        observer.disconnect();
        clearTimeout(timer);
        resolve(option);
      }
    });

    observer.observe(selectElement, { childList: true, subtree: true });

    const timer = setTimeout(() => {
      observer.disconnect();
      reject(new Error(`Option "${value}" not found after ${timeout}ms`));
    }, timeout);
  });
}
```

